{s:"料理を 作る のが 好きです。", t:"料理", r:"りょうり", w:["りょうりい","りょり","りょうる"], exp:"料理 đọc là りょうり（料 りょう、理 り）。りょうりい thêm い thừa、りょり thiếu âm う、りょうる đọc 理 thành る là sai。", voc:"料理（りょうり）：món ăn, nấu ăn； 作る（つくる）：làm, nấu； 好き（すき）：thích"},
{s:"肉を 食べます。", t:"肉", r:"にく", w:["にくう","にぐ","にき"], exp:"肉 đọc là にく（肉 にく）。にくう thêm う thừa、にぐ đọc く thành ぐ là sai、にき đọc く thành き là sai。", voc:"肉（にく）：thịt； 食べる（たべる）：ăn"},
{s:"魚を 食べます。", t:"魚", r:"さかな", w:["さかなあ","さがな","さきな"], exp:"魚 đọc là さかな（魚 さかな）。さかなあ thêm あ thừa、さがな đọc か thành が là sai、さきな đọc か thành き là sai。", voc:"魚（さかな）：cá； 食べる（たべる）：ăn"},
{s:"野菜を 食べます。", t:"野菜", r:"やさい", w:["やさいい","やざい","やさえ"], exp:"野菜 đọc là やさい（野 や、菜 さい）。やさいい thêm い thừa、やざい đọc 菜 thành ざい là sai、やさえ đọc 菜 thành さえ là sai。", voc:"野菜（やさい）：rau； 食べる（たべる）：ăn"},
{s:"果物を 食べます。", t:"果物", r:"くだもの", w:["くだものお","くたもの","くだまな"], exp:"果物 đọc là くだもの（果 くだ、物 もの）。くだものお thêm お thừa、くたもの đọc 果 thành くた là sai、くだまな đọc 物 thành まな là sai。", voc:"果物（くだもの）：trái cây； 食べる（たべる）：ăn"},
{s:"写真を とります。", t:"写真", r:"しゃしん", w:["しゃしんん","しゃじん","しょしん"], exp:"写真 đọc là しゃしん（写 しゃ、真 しん）。しゃしんん thêm ん thừa、しゃじん đọc 真 thành じん là sai、しょしん đọc 写 thành しょ là sai。", voc:"写真（しゃしん）：ảnh； 撮る（とる）：chụp"},
{s:"新聞を 読みます。", t:"新聞", r:"しんぶん", w:["しんぶんん","しんふん","しんぼん"], exp:"新聞 đọc là しんぶん（新 しん、聞 ぶん）。しんぶんん thêm ん thừa、しんふん đọc 聞 thành ふん là sai、しんぼん đọc 聞 thành ぼん là sai。", voc:"新聞（しんぶん）：báo； 読む（よむ）：đọc"},
{s:"病気に なりました。", t:"病気", r:"びょうき", w:["びょうきい","びょうぎ","びょうく"], exp:"病気 đọc là びょうき（病 びょう、気 き）。びょうきい thêm い thừa、びょうぎ đọc 気 thành ぎ là sai、びょうく đọc き thành く là sai。", voc:"病気（びょうき）：bệnh； なる：trở thành"},
{s:"薬を 飲みます。", t:"薬", r:"くすり", w:["くすりい","くずり","くする"], exp:"薬 đọc là くすり（薬 くすり）。くすりい thêm い thừa、くずり đọc す thành ず là sai、くする đọc り thành る là sai。", voc:"薬（くすり）：thuốc； 飲む（のむ）：uống"},
{s:"まいにち 体を 動かします。", t:"体", r:"からだ", w:["からだあ","からた","かりだ"], exp:"体 đọc là からだ（体 からだ、nghĩa là cơ thể）。からだあ thêm あ thừa、からた đọc だ thành た là sai、かりだ đọc ら thành り là sai。", voc:"体（からだ）：cơ thể； 動かす（うごかす）：vận động； 毎日（まいにち）：mỗi ngày"}
